rollback.sql:
DO $report_member_scope_rollback$
BEGIN
    LOCK TABLE clinlims.patient_report_release IN ACCESS EXCLUSIVE MODE;
    IF EXISTS (SELECT 1 FROM clinlims.patient_report_release WHERE member_scope_json IS NOT NULL OR member_scope_sha256 IS NOT NULL) THEN
        RAISE EXCEPTION 'Report membership snapshots exist; retain evidence and use a forward migration';
    END IF;
    ALTER TABLE clinlims.patient_report_release DROP CONSTRAINT ck_patient_report_release_member_scope;
    ALTER TABLE clinlims.patient_report_release DROP COLUMN member_scope_sha256;
    ALTER TABLE clinlims.patient_report_release DROP COLUMN member_scope_json;
END;
$report_member_scope_rollback$;
